use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Observation {
    pub url: String,
    pub title: String,
    pub viewport: [u32; 2],
    #[serde(skip_serializing_if = "Option::is_none")]
    pub focused: Option<String>,
    pub visible_text: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub state_hash: Option<String>,
    #[serde(default)]
    pub elements: Vec<ElementRef>,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct ElementRef {
    pub id: String,
    pub role: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub value: Option<String>,
    pub bbox: [f64; 4],
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub flags: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize, JsonSchema, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum Action {
    Click { id: String },
    Type {
        id: String,
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        submit: Option<bool>,
    },
    Select { id: String, value: String },
    Scroll { dx: i64, dy: i64 },
    Wait { ms: u64 },
    Navigate { url: String },
    Back,
    Extract {
        query: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        id: Option<String>,
    },
    Done { summary: String },
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct StepError {
    pub code: String,
    pub message: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct ExtractResult {
    pub query: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub id: Option<String>,
    pub value: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct StepResult {
    pub ok: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<StepError>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub new_state_hash: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extract: Option<ExtractResult>,
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn action_round_trip_click() {
        let action = Action::Click {
            id: "el_42".to_string(),
        };
        let value = serde_json::to_value(&action).expect("serialize action");
        assert_eq!(value, json!({"type": "click", "id": "el_42"}));
        let parsed: Action = serde_json::from_value(value).expect("deserialize action");
        assert_eq!(parsed, action);
    }

    #[test]
    fn observation_round_trip() {
        let observation = Observation {
            url: "https://example.com".to_string(),
            title: "Example".to_string(),
            viewport: [1280, 800],
            focused: Some("el_7".to_string()),
            visible_text: "Hello".to_string(),
            state_hash: Some("ab12cd".to_string()),
            elements: vec![ElementRef {
                id: "el_7".to_string(),
                role: "textbox".to_string(),
                name: Some("Email".to_string()),
                value: None,
                bbox: [10.0, 120.0, 400.0, 36.0],
                flags: vec!["focusable".to_string()],
            }],
        };
        let value = serde_json::to_value(&observation).expect("serialize observation");
        let parsed: Observation =
            serde_json::from_value(value).expect("deserialize observation");
        assert_eq!(parsed, observation);
    }

    #[test]
    fn step_result_round_trip() {
        let result = StepResult {
            ok: false,
            error: Some(StepError {
                code: "invalid_action".to_string(),
                message: "missing id".to_string(),
            }),
            new_state_hash: None,
            extract: None,
        };
        let value = serde_json::to_value(&result).expect("serialize step result");
        let parsed: StepResult = serde_json::from_value(value).expect("deserialize step result");
        assert_eq!(parsed, result);
    }

    #[test]
    fn step_result_with_extract_round_trip() {
        let result = StepResult {
            ok: true,
            error: None,
            new_state_hash: None,
            extract: Some(ExtractResult {
                query: "price".to_string(),
                id: Some("el_4".to_string()),
                value: "$10".to_string(),
            }),
        };
        let value = serde_json::to_value(&result).expect("serialize step result");
        let parsed: StepResult = serde_json::from_value(value).expect("deserialize step result");
        assert_eq!(parsed, result);
    }
}

use crate::browser::act::{action_result_err, action_result_ok, ActionApplier, ActionError};
use crate::browser::observe::{Observer, ObserverConfig};
use crate::browser::{Browser, BrowserError, BrowserResult};
use crate::types::{Action, Observation, StepResult};
use async_trait::async_trait;
use chromiumoxide::browser::{Browser as ChromiumBrowser, BrowserConfig};
use chromiumoxide::page::Page;
use futures::StreamExt;
use std::collections::HashMap;
use tokio::sync::Mutex;
use tokio::time::timeout;
use std::time::Duration;
use chromiumoxide_cdp::cdp::browser_protocol::dom::BackendNodeId;

#[derive(Clone, Debug)]
pub struct CdpConfig {
    pub headful: bool,
    pub initial_url: String,
    pub snapshot_timeout: Duration,
    pub action_timeout: Duration,
    pub max_elements: usize,
    pub max_text_len: usize,
}

impl Default for CdpConfig {
    fn default() -> Self {
        Self {
            headful: false,
            initial_url: "about:blank".to_string(),
            snapshot_timeout: Duration::from_secs(5),
            action_timeout: Duration::from_secs(10),
            max_elements: 50,
            max_text_len: 4000,
        }
    }
}

#[derive(Debug)]
struct Timeouts {
    snapshot: Duration,
    action: Duration,
}

#[derive(Debug)]
pub struct CdpBrowser {
    browser: Mutex<ChromiumBrowser>,
    page: Mutex<Page>,
    handler_task: tokio::task::JoinHandle<()>,
    observer: Observer,
    applier: ActionApplier,
    timeouts: Timeouts,
    element_map: Mutex<HashMap<String, BackendNodeId>>,
}

impl CdpBrowser {
    pub async fn bootstrap(config: CdpConfig) -> BrowserResult<()> {
        let browser = Self::launch(config).await?;
        browser.shutdown().await?;
        Ok(())
    }

    pub async fn launch(config: CdpConfig) -> BrowserResult<Self> {
        let mut builder = BrowserConfig::builder();
        if config.headful {
            builder = builder.with_head();
        }
        let browser_config = builder
            .build()
            .map_err(|err| BrowserError::new("config_error", err))?;
        let (browser, mut handler) = ChromiumBrowser::launch(browser_config)
            .await
            .map_err(|err| BrowserError::new("cdp_launch_failed", err.to_string()))?;
        let handler_task = tokio::spawn(async move {
            while let Some(_event) = handler.next().await {}
        });

        let page = browser
            .new_page("about:blank")
            .await
            .map_err(|err| BrowserError::new("cdp_page_failed", err.to_string()))?;
        if !config.initial_url.is_empty() && config.initial_url != "about:blank" {
            page.goto(config.initial_url.as_str())
                .await
                .map_err(|err| BrowserError::new("cdp_nav_failed", err.to_string()))?;
        }

        let observer = Observer::new(ObserverConfig {
            max_elements: config.max_elements,
            max_text_len: config.max_text_len,
        });

        Ok(Self {
            browser: Mutex::new(browser),
            page: Mutex::new(page),
            handler_task,
            observer,
            applier: ActionApplier::new(),
            timeouts: Timeouts {
                snapshot: config.snapshot_timeout,
                action: config.action_timeout,
            },
            element_map: Mutex::new(HashMap::new()),
        })
    }
}

#[async_trait]
impl Browser for CdpBrowser {
    async fn snapshot(&self) -> BrowserResult<Observation> {
        let snapshot = {
            let page = self.page.lock().await;
            let result = timeout(self.timeouts.snapshot, self.observer.snapshot(&page)).await;
            match result {
                Ok(snapshot) => snapshot?,
                Err(err) => {
                    return Err(BrowserError::new(
                        "timeout",
                        format!("snapshot timed out: {err}"),
                    ))
                }
            }
        };

        let mut map = self.element_map.lock().await;
        *map = snapshot.element_map;
        Ok(snapshot.observation)
    }

    async fn apply(&self, action: &Action) -> BrowserResult<StepResult> {
        let page = self.page.lock().await;
        let map = { self.element_map.lock().await.clone() };
        let result =
            timeout(self.timeouts.action, self.applier.apply(&page, action, Some(&map))).await;
        let step = match result {
            Ok(Ok(outcome)) => action_result_ok(outcome.extract),
            Ok(Err(err)) => action_result_err(err),
            Err(err) => action_result_err(ActionError::new(
                "timeout",
                format!("action timed out: {err}"),
            )),
        };
        Ok(step)
    }

    async fn shutdown(&self) -> BrowserResult<()> {
        let mut browser = self.browser.lock().await;
        browser.close().await?;
        self.handler_task.abort();
        Ok(())
    }
}

impl From<chromiumoxide::error::CdpError> for BrowserError {
    fn from(err: chromiumoxide::error::CdpError) -> Self {
        BrowserError::new("cdp_error", err.to_string())
    }
}

impl Drop for CdpBrowser {
    fn drop(&mut self) {
        self.handler_task.abort();
    }
}

